-- MediStock Pro: PostgreSQL schema (works on Neon). Safe to run once on an empty database.
CREATE TABLE IF NOT EXISTS users(id SERIAL PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(150) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role VARCHAR(10) NOT NULL DEFAULT 'staff' CHECK(role IN('admin','staff')),is_active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS medicines(id SERIAL PRIMARY KEY,name VARCHAR(150) NOT NULL,generic_name VARCHAR(150),brand VARCHAR(100),category VARCHAR(80),dosage_form VARCHAR(50),strength VARCHAR(50),manufacturer VARCHAR(120),barcode VARCHAR(60) UNIQUE,description TEXT,requires_prescription BOOLEAN DEFAULT FALSE,min_stock INT NOT NULL DEFAULT 10,tax_percent DECIMAL(5,2) NOT NULL DEFAULT 12.00,is_archived BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_med_name ON medicines(name);CREATE INDEX IF NOT EXISTS idx_med_generic ON medicines(generic_name);CREATE INDEX IF NOT EXISTS idx_med_cat ON medicines(category);
CREATE TABLE IF NOT EXISTS suppliers(id SERIAL PRIMARY KEY,company_name VARCHAR(150) NOT NULL,contact_person VARCHAR(100),phone VARCHAR(20),email VARCHAR(150),address TEXT,gstin VARCHAR(20),notes TEXT,is_archived BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS purchases(id SERIAL PRIMARY KEY,supplier_id INT NOT NULL REFERENCES suppliers(id),reference_no VARCHAR(50) NOT NULL UNIQUE,total_amount DECIMAL(12,2) NOT NULL,status VARCHAR(10) NOT NULL DEFAULT 'received' CHECK(status IN('received','cancelled')),created_by INT NOT NULL REFERENCES users(id),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_pur_date ON purchases(created_at);
CREATE TABLE IF NOT EXISTS batches(id SERIAL PRIMARY KEY,medicine_id INT NOT NULL REFERENCES medicines(id),supplier_id INT REFERENCES suppliers(id),purchase_id INT REFERENCES purchases(id),batch_no VARCHAR(50) NOT NULL,purchase_price DECIMAL(10,2) NOT NULL,selling_price DECIMAL(10,2) NOT NULL,received_qty INT NOT NULL,available_qty INT NOT NULL,mfg_date DATE,expiry_date DATE NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT chk_qty CHECK(available_qty>=0 AND available_qty<=received_qty),UNIQUE(medicine_id,batch_no));
CREATE INDEX IF NOT EXISTS idx_batch_exp ON batches(expiry_date);
CREATE TABLE IF NOT EXISTS purchase_items(id SERIAL PRIMARY KEY,purchase_id INT NOT NULL REFERENCES purchases(id) ON DELETE CASCADE,medicine_id INT NOT NULL REFERENCES medicines(id),batch_id INT NOT NULL REFERENCES batches(id),quantity INT NOT NULL,purchase_price DECIMAL(10,2) NOT NULL,selling_price DECIMAL(10,2) NOT NULL,expiry_date DATE NOT NULL);
CREATE TABLE IF NOT EXISTS sales(id SERIAL PRIMARY KEY,invoice_no VARCHAR(30) NOT NULL UNIQUE,idempotency_key VARCHAR(64) UNIQUE,customer_name VARCHAR(100),subtotal DECIMAL(12,2) NOT NULL,discount DECIMAL(12,2) NOT NULL DEFAULT 0,tax DECIMAL(12,2) NOT NULL,total DECIMAL(12,2) NOT NULL,payment_method VARCHAR(10) NOT NULL CHECK(payment_method IN('cash','upi','card','other')),status VARCHAR(10) NOT NULL DEFAULT 'completed' CHECK(status IN('completed','returned','cancelled')),created_by INT NOT NULL REFERENCES users(id),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_sales_date ON sales(created_at);
CREATE TABLE IF NOT EXISTS sale_items(id SERIAL PRIMARY KEY,sale_id INT NOT NULL REFERENCES sales(id),medicine_id INT NOT NULL REFERENCES medicines(id),batch_id INT NOT NULL REFERENCES batches(id),quantity INT NOT NULL,unit_price DECIMAL(10,2) NOT NULL,unit_cost DECIMAL(10,2) NOT NULL,discount DECIMAL(10,2) NOT NULL DEFAULT 0,tax_percent DECIMAL(5,2) NOT NULL,tax_amount DECIMAL(10,2) NOT NULL,line_total DECIMAL(12,2) NOT NULL);
CREATE TABLE IF NOT EXISTS stock_movements(id SERIAL PRIMARY KEY,batch_id INT NOT NULL REFERENCES batches(id),medicine_id INT NOT NULL REFERENCES medicines(id),type VARCHAR(12) NOT NULL CHECK(type IN('purchase','sale','return','adjustment')),quantity_change INT NOT NULL,reason VARCHAR(255),reference VARCHAR(50),user_id INT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_mov_date ON stock_movements(created_at);
CREATE TABLE IF NOT EXISTS notifications(id SERIAL PRIMARY KEY,category VARCHAR(12) NOT NULL CHECK(category IN('low_stock','expiring','expired','purchase','sale','inventory')),message VARCHAR(255) NOT NULL,dedupe_key VARCHAR(100) UNIQUE,is_read BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS returns(id SERIAL PRIMARY KEY,sale_id INT NOT NULL REFERENCES sales(id),reason VARCHAR(255),refund_amount DECIMAL(12,2) NOT NULL,created_by INT NOT NULL REFERENCES users(id),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS return_items(id SERIAL PRIMARY KEY,return_id INT NOT NULL REFERENCES returns(id) ON DELETE CASCADE,sale_item_id INT NOT NULL REFERENCES sale_items(id),quantity INT NOT NULL);
CREATE TABLE IF NOT EXISTS audit_logs(id SERIAL PRIMARY KEY,user_id INT,action VARCHAR(80) NOT NULL,entity VARCHAR(50),entity_id INT,details JSONB,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS pharmacy_settings(id INT PRIMARY KEY DEFAULT 1,name VARCHAR(150) DEFAULT 'MediStock Pharmacy',address TEXT,phone VARCHAR(20),gstin VARCHAR(20),expiry_critical_days INT DEFAULT 30,expiry_warning_days INT DEFAULT 90);
